// Replace errors with a safe default
Table.ReplaceErrorValues(Typed, {{"Salary", 0}})

// Trim and clean text keys before joining
Table.TransformColumns(Source, {{"Department", each Text.Trim(Text.Clean(_)), type text}})

// Add a filter
High Earners = CALCULATE ( [Total_Employee], Employee[MonthlyIncome] > 10000 )

// Ignore a filter
All Departments = CALCULATE ( [Total_Employee], REMOVEFILTERS ( Department ) )

// Keep only one filter, clear the rest
Sales Only = CALCULATE ( [Total_Employee], ALLEXCEPT ( Employee, Employee[Department] ) )

// Percent of total
% of Workforce =
DIVIDE ( [Total_Employee], CALCULATE ( [Total_Employee], REMOVEFILTERS ( ) ) )

// Static role: Sales only
[Department] = "Sales"

// Dynamic role: user sees their own department
[Department] =
LOOKUPVALUE (
  UserSecurity[Department],
  UserSecurity[Email], USERPRINCIPALNAME ()
)
